import React from "react";
import '../css/login.css';
import { Link, useNavigate } from "react-router-dom";

class Welcome extends React.Component {
    render() {
        return (
            <main className="container-fluid vh-100 d-flex align-items-center justify-content-center p-0">
                {/* تصویر ثابت در گوشه بالا چپ */}
                <img
                    src="../img/aaa.png"
                    alt="fixed logo"
                    className="fixed-top-left"
                />

                {/* باکس اصلی - بدون تغییر */}
                <div className="login-box-login shadow text-center item-back boder p-4 rounded-5">
                    <img src="../img/aaa.png" alt="center logo" />
                    <div className="mt-5">
                        <p>
                            <b>سرویسی امن و راحت برای خدمت رسانی به مشتریان</b>
                        </p>
                        <div className="mx-4 mt-4">
                            <a className="btn btn-primary w-100 rounded-3">شروع</a>
                        </div>
                    </div>
                </div>
            </main>
        );
    }
}

export default Welcome;
